// Crowd cast (Alex, Malik, and all 19 non-roster town walkers); notes/conversation-design.md stage C9.
const freezeDeep=o=>{if(!o||typeof o!=='object')return o;Object.freeze(o);for(const v of Object.values(o))freezeDeep(v);return o};

function makeCrowdCast(c){
 const id=c.id;
 return freezeDeep({
  id,
  name:c.name,
  personId:c.personId,
  kind:'crowd',
  voice:c.voice,
  facts:{name:c.name,job:c.job,home:c.home,hint:c.hint},
  bye:[
   {if:{weather:'rain'},t:`Stay dry out there—${c.byeRain}`},
   {if:{weather:'snow'},t:`Mind the ice—${c.byeSnow}`},
   {if:{tierMin:'friend'},t:`Good catching up, friend. ${c.byeFriend}`},
   {t:c.byeDefault}
  ],
  nodes:[
   {id:`${id}.door`,entry:true,when:{place:['door','doorway']},do:[{meet:true}],say:[
    {if:{met:false},w:5,t:[`Oh, hello! I am {name}—always nice to meet a new face.`]},
    {if:{weather:'rain'},w:4,t:[`Wet doorstep today! ${c.rain}`]},
    {if:{weather:'snow'},w:4,t:[`Chilly out on the steps! ${c.snow}`]},
    {if:{hired:'ridgeline'},w:4,t:[`Spotted that Ridgeline vest on the step. ${c.workVest}`]},
    {if:{tierMin:'friend'},w:3,t:[`Glad you stopped by—I am {name}, and you are always welcome here.`]},
    {if:{period:'morning'},w:1,t:[`Morning! ${c.morning}`]},
    {if:{period:'evening'},w:1,t:[`Evening! ${c.evening}`]},
    {t:[`${c.door}`]}
   ],replies:[
    {label:'What do you do for work?',go:`${id}.work`},
    {label:'Heard anything round town?',go:`${id}.rumour`},
    {label:'Any local tips for me?',go:`${id}.tip`}
   ]},

   {id:`${id}.open`,entry:true,do:[{meet:true}],say:[
    {if:{met:false},w:5,t:[`Hi there! I am {name}.`,`{home}`]},
    {if:{hired:'ridgeline'},w:4,t:[`${c.vest}`]},
    {if:{weather:'rain'},w:4,t:[`${c.rain}`]},
    {if:{weather:'storm'},w:4,t:[`${c.storm}`]},
    {if:{weather:'snow'},w:4,t:[`${c.snow}`]},
    {if:{weather:'fog'},w:4,t:[`${c.fog}`]},
    {if:{tierMin:'close'},w:3,t:[`${c.close}`]},
    {if:{tierMin:'friend'},w:2,t:[`${c.friend}`]},
    {if:{period:'morning'},w:1,t:[`Good morning! ${c.morning}`]},
    {if:{period:'afternoon'},w:1,t:[`Afternoon! ${c.afternoon}`]},
    {if:{period:'evening'},w:1,t:[`Good evening! ${c.evening}`]},
    {if:{period:'night'},w:1,t:[`Quiet night out here. ${c.night}`]},
    {t:[`${c.open}`]}
   ],replies:[
    {label:'What do you do for work?',go:`${id}.work`},
    {label:'Heard anything round town?',go:`${id}.rumour`},
    {label:'Any local tips for me?',go:`${id}.tip`}
   ]},

   {id:`${id}.work`,say:[
    {if:{hired:'ridgeline'},w:2,t:[`{job} ${c.workVest}`],do:[{standing:1}]},
    {t:[`{job}`,`${c.workExtra}`],do:[{standing:1}]}
   ],replies:[
    {label:'Heard anything round town?',go:`${id}.rumour`},
    {label:'Any local tips for me?',go:`${id}.tip`}
   ]},

   {id:`${id}.rumour`,say:[
    {t:[`${c.rumour}`]}
   ],end:true},

   {id:`${id}.tip`,say:[
    {t:[`{hint}`]}
   ],end:true}
  ]
 });
}

